def stage_values(row):
    """Etapes d'une passe et leur somme ; None si une etape manque ou n'est pas un entier."""
    st = row.get('stages') or {}
    if not all(is_int(st.get(k)) for keys in STAGES.values() for k in keys):
        return None
    parts = {name: sum(st[k] for k in keys) for name, keys in STAGES.items()}
    return parts, sum(parts.values())

c8dd.check_mutant:
def check_mutant(steps, out):
    m = steps.get('mutant') or {}
    if not m.get('applied') or not m.get('built'):
        out['refused'].append('mutant appareil non juge')
        return
    run = m.get('run') or {}
    code = run.get('code')
    if code not in (0, 2, 3) or run.get('timeout'):
        out['refused'].append('mutant appareil sans preuve')
        return
    reference = m.get('reference') or {}
    differs = code != 0 or any(d != reference.get('digest') for d in run.get('digests') or []) or any(
        f.get('niveaux_sha256') != reference.get('niveaux_sha256') or f.get('table_sha256') !=
        reference.get('table_sha256') for f in run.get('complets') or []) or not run.get('digests')
    out['stats']['mutant'] = 'tue' if differs else 'survivant'
    if not differs:
        out['rejected'].append('mutant appareil survivant (flux_sans_attente_appareil)')

