def run_complete(run, passes, digests):
    """Sonde jouee en entier : passes attendues conformes, temps entiers ; si digests : une empreinte complete par
    passe (MHGP12DP, niveaux, table sans ecart)."""
    if not isinstance(run, dict) or run.get('unreadable', 1) != 0 or run.get('code') != 0:
        return False
    rows = run.get('passes') or []
    if len(rows) != passes or any(r.get('status') != 'ok' or not is_int(r.get('wall_ns')) for r in rows):
        return False
    if digests:
        full = run.get('complets') or []
        if len(run.get('digests') or []) != passes or len(full) != passes:
            return False
        if not all(is_hex(d) for d in run['digests']) or any(
                not isinstance(f, dict) or not is_hex(f.get('niveaux_sha256')) or not is_hex(f.get('table_sha256'))
                or f.get('table_ecarts') != 0 for f in full):
            return False
    return True

