pilot.parse:
def parse(text):
    """Lignes d'une sonde du catalogue : passes (et leur ligne << sorties >>), empreintes, empreintes completes."""
    out = {'passes': [], 'digests': [], 'complets': [], 'open': None, 'exit': None, 'unreadable': 0}
    if not text.isascii():
        out['unreadable'] = 1
        return out
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line, object_pairs_hook=base.unique_object, parse_constant=base.reject_constant)
        except (ValueError, RecursionError):
            out['unreadable'] += 1
            continue
        phase = obj.get('phase') if isinstance(obj, dict) else None
        if out['exit'] is not None or phase is None:
            out['unreadable'] += 1
        elif phase == 'catalogue':
            out['passes'].append(obj)
        elif phase == 'sorties' and out['passes'] and obj.get('pass') == out['passes'][-1].get('pass'):
            out['passes'][-1]['sorties'] = obj
        elif phase == 'digest':
            out['digests'].append(obj.get('catalogue_sha256'))
        elif phase == 'digest_complet':
            out['complets'].append({k: obj.get(k) for k in ('niveaux_sha256', 'table_sha256', 'table_ecarts')})
        elif phase in ('open', 'exit') and out[phase] is None:
            out[phase] = obj
        else:
            out['unreadable'] += 1
    for p in out['passes']:
        diag, dev, sorties = p.get('diagnostics') or {}, p.get('device') or {}, p.get('sorties') or {}
        p['stages'] = {k: diag.get(k) for k in STAGE_DIAG}
        p['stages'].update(transfer_ns=dev.get('transfer_ns'), publish_ns=dev.get('publish_ns'),
                           outputs_ns=sorties.get('outputs_ns', 0))
    return out
